<?php declare(strict_types=1); require_once __DIR__.'/lib/auth.php'; $admin=require_admin(); $msg=''; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0); $days=max(1,min(3650,(int)($_POST['days']??30))); try { $q=db()->prepare("UPDATE users SET expires_at=CASE WHEN expires_at IS NOT NULL AND expires_at>NOW() THEN DATE_ADD(expires_at, INTERVAL ? DAY) ELSE DATE_ADD(NOW(), INTERVAL ? DAY) END, status='active' WHERE id=? AND role='user'"); $q->execute([$days,$days,$id]); $msg='Đã gia hạn tài khoản.'; } catch(Throwable $e){$error='Không thể gia hạn.';} } $users=db()->query("SELECT id,name,email,status,expires_at,last_login_at,created_at FROM users WHERE role='user' ORDER BY id DESC")->fetchAll(); ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý tài khoản</title><link rel="stylesheet" href="assets/css/app.css"></head><body><main class="app"><header class="top"><div class="brand"><div class="logo">▶</div><div><h1>Quản lý tài khoản</h1><p>VideoDubing AI · Admin</p></div></div><div class="userbar"><span><?=htmlspecialchars($admin['name'],ENT_QUOTES,'UTF-8')?></span><a href="logout.php">Đăng xuất</a></div></header><section class="panel"><div class="section-title">Tài khoản User</div><?php if($msg):?><div class="alert ok"><?=htmlspecialchars($msg)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=htmlspecialchars($error)?></div><?php endif;?><div class="table-wrap"><table><thead><tr><th>Họ tên</th><th>Email</th><th>Trạng thái</th><th>Hạn sử dụng</th><th>Gia hạn</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=htmlspecialchars($u['name'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><?=htmlspecialchars($u['status'])?></td><td><?=htmlspecialchars((string)$u['expires_at'])?></td><td><form method="post" class="renew"><input type="hidden" name="id" value="<?=$u['id']?>"><select name="days"><option value="7">7 ngày</option><option value="30" selected>30 ngày</option><option value="90">90 ngày</option><option value="180">180 ngày</option><option value="365">365 ngày</option></select><button class="secondary">Gia hạn</button></form></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
